import {pinVoltage,poweredDevice,logic} from './bus-electrical.js';
export function attachThermocoupleRuntime(runtime,engine,initial){let project=initial,states=new Map(),disposed=false,busy=false,key='';
 const refresh=()=>{if(disposed||busy)return;busy=true;try{const dc=engine.solution,cycle=runtime.cpu.cycles,drivers=[];for(const d of states.values()){const c=project.components.find(c=>c.id===d.id),p=poweredDevice(dc,d.id,{min:3,max:5.5}),cs=logic(pinVoltage(dc,d.id,'CS'),p.voltage),clock=logic(pinVoltage(dc,d.id,'SCK'),p.voltage),minus=pinVoltage(dc,d.id,'T-'),plus=pinVoltage(dc,d.id,'T+');if(d.powered&&!p.powered){d.word=0;d.epoch++;d.pending=null;d.started=false;}Object.assign(d,p);d.overvoltage=['SCK','CS'].some(pin=>pinVoltage(dc,d.id,pin)>p.voltage+.3);d.connected=p.powered&&!d.overvoltage&&cs!==null&&clock!==null;
 if(d.connected){if(cs===true&&(!d.started||d.cs===false)){d.started=true;d.pending=cycle+220*16000;const epoch=++d.epoch;runtime.cpu.addClockEvent(()=>{if(!disposed&&epoch===d.epoch)refresh();},220*16000);}if(cs===false){if(d.cs!==false){d.pending=null;d.epoch++;d.bit=15;}if(clock===false&&d.clock===true)d.bit--;}
 if(d.pending!==null&&cycle>=d.pending){d.open=!!c.params.open||!Number.isFinite(minus)||Math.abs(minus)>.02||!Number.isFinite(plus);d.temperature=d.open?0:Math.max(0,Math.min(1023.75,(plus-minus)/.000041+(c.params.ambient??25)));d.word=(Math.round(d.temperature*4)<<3)|(d.open?4:0);d.samples++;d.pending=null;}
 if(cs===false&&d.bit>0)drivers.push({endpoint:d.id+':SO',voltage:(d.word>>d.bit)&1?p.voltage:0,ohms:50});}
 if(p.powered&&!c.params.open&&Number.isFinite(minus)&&Math.abs(minus)<.02)drivers.push({endpoint:d.id+':T+',voltage:minus+((c.params.temperature??25)-(c.params.ambient??25))*.000041,ohms:1});d.cs=cs;d.clock=clock;
 }const next=JSON.stringify(drivers);if(next!==key){key=next;engine.setDrivers('thermocouple',drivers);}}finally{busy=false;}};
 const reconcile=()=>{const ids=new Set();for(const c of project.components.filter(c=>c.type==='max6675')){ids.add(c.id);if(!states.has(c.id))states.set(c.id,{id:c.id,powered:false,epoch:0,started:false,pending:null,word:0,samples:0,temperature:0,open:false,bit:15,cs:null,clock:null});}for(const id of states.keys())if(!ids.has(id))states.delete(id);refresh();};reconcile();const unsubscribe=engine.subscribe(refresh);return{updateProject(next){project=next;reconcile();},snapshot(){refresh();return{modules:Object.fromEntries([...states].map(([id,d])=>[id,{type:'max6675',powered:d.powered,connected:d.connected,overvoltage:d.overvoltage,temperature:d.temperature,open:d.open,samples:d.samples,word:d.word,converting:d.pending!==null}]))};},dispose(){disposed=true;for(const d of states.values())d.epoch++;unsubscribe();engine.setDrivers('thermocouple',[]);}};
}
